import unittest
from pagination import collect_pages


class PaginationTests(unittest.TestCase):
    def test_falsey_cursors_and_empty_pages(self):
        calls = []
        pages = {
            None: {'items': [], 'next': ''},
            '': {'items': [], 'next': 0},
            0: {'items': [{'id': 1}], 'next': None},
        }
        def fetch(cursor):
            calls.append(cursor)
            return pages[cursor]
        self.assertEqual(collect_pages(fetch), [{'id': 1}])
