    def test_duplicates_keep_first_item_and_position(self):
        first = {'id': 0, 'value': 'first'}
        second = {'id': 2}
        third = {'id': 1}
        pages = {
            None: {'items': [first, second, {'id': 0}], 'next': 'a'},
            'a': {'items': [{'id': 2}, third, {'id': 0}], 'next': None},
        }
        result = collect_pages(pages.__getitem__)
        self.assertEqual(result, [first, second, third])
        self.assertIs(result[0], first)

    def test_repeated_cursors_raise_before_fetch(self):
        for cursors in [('a', 'a'), ('a', 'b', 'a'), ('', ''), (0, 0)]:
            with self.subTest(cursors=cursors):
                calls = []
                next_cursors = iter(cursors)
                def fetch(cursor):
                    calls.append(cursor)
                    return {'items': [], 'next': next(next_cursors)}
                with self.assertRaises(ValueError):
                    collect_pages(fetch)
                self.assertEqual(calls, [None] + list(cursors[:-1]))

    def test_fetch_exception_propagates_unchanged(self):
        failure = RuntimeError('fetch failed')
        calls = []
        def fetch(cursor):
            calls.append(cursor)
            if cursor is None:
                return {'items': [{'id': 0}], 'next': 'a'}
            raise failure
        with self.assertRaises(RuntimeError) as caught:
            collect_pages(fetch)
        self.assertIs(caught.exception, failure)
        self.assertEqual(calls, [None, 'a'])

